const DOMAIN_REGEX = /^(?=.{1,253}$)([a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)+[a-zA-Z]{2,}$/;
function d(a,b,c,dd){ return `${"a".repeat(a)}.${"a".repeat(b)}.${"a".repeat(c)}.${"a".repeat(dd)}`; }
const d253 = d(63,63,63,61);
const d254 = d(63,63,63,62);
console.log(d253.length, DOMAIN_REGEX.test(d253));
console.log(d254.length, DOMAIN_REGEX.test(d254));
// other edge: 253 with different splits
const alt253 = "a".repeat(63)+"."+"b".repeat(63)+"."+"c".repeat(57)+"."+"d".repeat(63)+".co";
console.log("alt253 len", alt253.length, DOMAIN_REGEX.test(alt253));
// 254 alt
console.log("long label still rejected", DOMAIN_REGEX.test("a".repeat(64)+".com"));
// check trailing newline trick
console.log("newline", DOMAIN_REGEX.test("example.com\n"));
console.log("253 + newline len", (d253+"\n").length, DOMAIN_REGEX.test(d253+"\n"));
'",
