const NEW = /^(?=.{1,253}$)([a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)+[a-zA-Z]{2,}$/;
const oldRe = new RegExp(OLD), newRe = new RegExp(NEW);
// Random valid-label generator
function randLabel(len){
  const chars="abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
  let s=chars[Math.floor(Math.random()*chars.length)];
  for(let i=1;i<len-1;i++){ const c="abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-"; s+=c[Math.floor(Math.random()*c.length)]; }
  if(len>1) s+=chars[Math.floor(Math.random()*chars.length)];
  return s;
}
function randTLD(len){
  const chars="abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
  let s=""; for(let i=0;i<len;i++) s+=chars[Math.floor(Math.random()*chars.length)];
  return s;
}
