    if(remaining < 2) break;
    const maxL = Math.min(63, remaining-1);
    const len = 1 + Math.floor(Math.random()*maxL);
    labels.push(randLabel(len));
    remaining -= (len+1);
    if(labels.length>20) break;
  }
  // adjust: construct domain, then pad/trim? Simpler: construct then check lengths
  let domain = labels.length? labels.join(".")+"."+randTLD(tldLen) : randTLD(tldLen);
