  const o = oldRe.test(domain), n = newRe.test(domain);
  const L = domain.length;
  if(L<=253 && o!==n){ bad.push(["LE253 mismatch", L, domain]); }
  if(L>253 && n){ bad.push(["GT253 accepted", L, domain]); }
  if(L===253 && o) checked253++;
  if(L===254 && o) checked254++;
  if(bad.length>5) break;
}
