  // Simple: use many small labels to hit exactly 253
  // "a."*125 + tld(3) = 253 exactly (tested). Vary chars.
  let s="";
  for(let k=0;k<125;k++) s += "ab"[k%2] + ".";
  s += randTLD(3);
  total++;
  if(!newRe.test(s)) fails++;
}
console.log("exact253 varied:", total-fails, "/", total);
